import sys

def construct_array(n, s, k):
    if n == 1:
        return [s] if k == 0 else [-1]
    for i in range(n):
        for j in range(s + 1):
            result = [j] * i + [s - j * i] + [0] * (n - i - 1)
            if result[-1] < 0:
                continue
            current_k = sum(abs(result[x] - result[y]) for x in range(n) for y in range(x + 1, n))
            if current_k == k:
                return result
    return [-1]

def main():
    import sys
    input = sys.stdin.read().split()
    q = int(input[0])
    index = 1
    results = []
    for _ in range(q):
        n = int(input[index])
        s = int(input[index + 1])
        k = int(input[index + 2])
        index += 3
        results.append(construct_array(n, s, k))
    for result in results:
        if result == [-1]:
            print(-1)
        else:
            print(" ".join(map(str, result)))

main()
